    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.13, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*70, 0.055, 1.8]
  ];
  let act=0, inh=0, mod=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    act += Math.sin(d*f - t*sp);
    inh += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    mod += Math.cos(d*f*0.5 - t*sp*0.8 + 2.0);
  }
  act/=8; inh/=8; mod/=8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.02+sy*0.05-t*0.7)+Math.cos(sx*0.05-sy*0.02+t*0.9))/4 + Math.sin((sx+sy)*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
