  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + mod*0.2)*2.2);
  const r2 = Math.tanh((act*0.5 + inh*0.3 - mod*0.8 + spiral*0.5)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.cos(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.25;
  const detail = Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.2-sy*0.3+t*2.5)*0.1;
  const pulse = 1.0 + Math.sin(t*0.4)*0.05;
  const blend = (r1*0.5+r2*0.2+cell*0.25+detail)*pulse;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)/320*0.25;
  const pal = [[4,10,48],[10,40,82],[16,78,108],[22,120,125],[50,158,115],[110,178,90],[185,188,55],[218,155,48],[208,105,52],[175,62,65],[120,38,72],[60,22,60],[20,10,45],[4,10,48]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(r1*Math.PI)*0.18;
  const edge = Math.abs(r1)>0.72?1.14:Math.abs(r2)>0.6?1.06:1.0;
